--- from: 
---@class OSManageOperateStatementItemCell
---@field Env                           	OSManageOperateStatementItemCell        
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TextOrder                     	UnityEngine.RectTransform               
---@field ImgLight                      	UnityEngine.RectTransform               
---@field Currency                      	Engine.Modules.LuaBehaviour             
---@field ImgFill                       	UnityEngine.UI.Image                    
---@field OnList                        	UnityEngine.RectTransform               
---@field NotListed                     	UnityEngine.RectTransform               
---@field Lock                          	UnityEngine.RectTransform               
local OSManageOperateStatementItemCell = Class('OSManageOperateStatementItemCell')
local CurryEnvPath = "Game.Behaviours.CommonCurrencyNode"
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
function OSManageOperateStatementItemCell:__init()

end

function OSManageOperateStatementItemCell:Awake()
    self:InitNodeEnv()
    self:AddUIClick()
end

function OSManageOperateStatementItemCell:AddUIClick()
    SetButtonAction(self.controller.gameObject,Bind(self,self.OnCellClick))
end

function OSManageOperateStatementItemCell:OnCellClick()
    if self.data.isLock then
        local vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(self.index)
        local str = GameUtils.GetUnlockDescr(vo.unlockType, vo.unlockNum)
        GameUtils.Toast(str)
    end
end

function OSManageOperateStatementItemCell:InitNodeEnv()
    if self.Currency then
        local env = CfUtils.GetLuaScr(self.Currency,CurryEnvPath)
        if env then
            self.curCurrencyEnv = env
        end
    end
end

function OSManageOperateStatementItemCell:__delete()
    self.data = nil
    self.index = nil
    self.curCurrencyEnv = nil
end

function OSManageOperateStatementItemCell:RefreshUI(data,i)
    KTool.SetActive(self.controller.gameObject,true)
    self.index = i
    self.data = data

    CfUtils.FillText(self.TextOrder,self.index)
    CfUtils.FillText(self.TextOrder1,self.index)
    CfUtils.FillText(self.TextOrder2,self.index)
    if data.isLock then
        KTool.SetActive(self.Lock.gameObject,true)
        KTool.SetActive(self.NotListed.gameObject,false)
        KTool.SetActive(self.OnList.gameObject,false)
        return
    end

    KTool.SetActive(self.Lock.gameObject,false)
    self:RefreshSellState()

end

function OSManageOperateStatementItemCell:RefreshSellState()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isSell =  component:GetCurMenuIsSell(self.index)
    KTool.SetActive(self.NotListed.gameObject,not isSell)
    KTool.SetActive(self.OnList.gameObject,isSell)
    if isSell then
        local menuInfo = component:GetCurIndexMenuInfo(self.index)
        if not isNull(menuInfo) and menuInfo:IsSell() then
            local baseTime = component:GetMenuBaseTime()
            local remainNum =  menuInfo.totalSaleNum - math.floor((menuInfo.totalTime - menuInfo:GetRemainTime())/baseTime)
            self.ImgFill.fillAmount = remainNum/menuInfo.totalSaleNum
        end
        ---货币和图标
        local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
        local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
        local baseIncome = component:GetSingeMenuSaleIncome(self.index)
        self.curCurrencyEnv:SetCurrencyShow(goodsId,baseIncome,localize("_num_/份",{_num_ = baseIncome}))
    end
end

function OSManageOperateStatementItemCell:Start()
end

function OSManageOperateStatementItemCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OSManageOperateStatementItemCell